			payload: `{"invocationNum": 0, "workspacePaths": ["/tmp/not-enrolled-repo"]}`,
			want:    "{}",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			for k, v := range tt.env {
				os.Setenv(k, v)
				defer os.Unsetenv(k)
